import { Controller, Get, Patch, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const USE_STATUSES = ['사용', '미사용'];

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function isBlank(v: unknown): boolean {
  return v === undefined || v === null || v === '';
}

function isNumeric(v: unknown): boolean {
  if (typeof v === 'number') {
    return Number.isFinite(v);
  }
  if (typeof v === 'string' && v.trim() !== '') {
    return Number.isFinite(Number(v));
  }
  return false;
}

function optInt(v: unknown, label: string): number | null {
  if (isBlank(v)) {
    return null;
  }
  if (!isNumeric(v) || !Number.isInteger(Number(v))) {
    throw invalid(label + ' 값은 정수여야 합니다.');
  }
  return Number(v);
}

function optDate(v: unknown, label: string): string | null {
  if (isBlank(v)) {
    return null;
  }
  if (typeof v !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(v)) {
    throw invalid(label + ' 값은 YYYY-MM-DD 형식이어야 합니다.');
  }
  return v;
}

function optNonNegative(v: unknown, label: string): number | null {
  if (isBlank(v)) {
    return null;
  }
  if (!isNumeric(v) || Number(v) < 0) {
    throw invalid(label + ' 값은 0 이상의 숫자여야 합니다.');
  }
  return Number(v);
}

function pageOf(query: Record<string, unknown>): { page: number; size: number } {
  const page = isBlank(query['page']) ? 0 : Number(query['page']);
  const size = isBlank(query['size']) ? DEFAULT_SIZE : Number(query['size']);
  if (!Number.isInteger(page) || page < 0) {
    throw invalid('page는 0 이상의 정수여야 합니다.');
  }
  if (!Number.isInteger(size) || size < 1) {
    throw invalid('size는 1 이상의 정수여야 합니다.');
  }
  return { page, size: Math.min(size, MAX_SIZE) };
}

@Controller('api/v1')
export class FnSfr01808Controller {
  @Get('/annual-leaves')
  async listAnnualLeaves(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '근태 담당자');
    const query = checks.queryOf(req.query) as Record<string, unknown>;
    const { page, size } = pageOf(query);
    const employeeId = optInt(query['employeeId'], '임직원');
    const baseYear = optInt(query['baseYear'], '기준연도');
    const departmentId = optInt(query['departmentId'], '부서 ID');
    return transaction(async (db) => {
      const where: string[] = ['1 = 1'];
      const params: Record<string, unknown> = {};
      if (employeeId !== null) {
        where.push('a.employee_id = CAST(:employeeId AS bigint)');
        params.employeeId = employeeId;
      }
      if (baseYear !== null) {
        where.push('a.base_year = CAST(:baseYear AS integer)');
        params.baseYear = baseYear;
      }
      if (departmentId !== null) {
        where.push('e.department_id = CAST(:departmentId AS bigint)');
        params.departmentId = departmentId;
      }
      const from = ' FROM annual_leave a JOIN employee e ON e.employee_id = a.employee_id WHERE ' + where.join(' AND ');
      const totalRows = await db.query('SELECT COUNT(*) AS total' + from, params);
      const items = await db.query(
        'SELECT a.annual_leave_id AS "annualLeaveId", a.employee_id AS "employeeId", a.base_year AS "baseYear", ' +
          'a.granted_days AS "grantedDays", a.used_days AS "usedDays", a.remaining_days AS "remainingDays"' +
          from +
          ' ORDER BY a.base_year DESC, a.annual_leave_id LIMIT CAST(:limit AS integer) OFFSET CAST(:offset AS integer)',
        { ...params, limit: size, offset: page * size },
      );
      return { items, page, size, total: Number(totalRows[0].total) };
    });
  }

  @Get('/leave-usages')
  async listLeaveUsages(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '근태 담당자');
    const query = checks.queryOf(req.query) as Record<string, unknown>;
    const { page, size } = pageOf(query);
    const annualLeaveId = optInt(query['annualLeaveId'], '연차 ID');
    const startDate = optDate(query['startDate'], '조회 시작일');
    const endDate = optDate(query['endDate'], '조회 종료일');
    return transaction(async (db) => {
      const where: string[] = ['1 = 1'];
      const params: Record<string, unknown> = {};
      if (annualLeaveId !== null) {
        where.push('u.annual_leave_id = CAST(:annualLeaveId AS bigint)');
        params.annualLeaveId = annualLeaveId;
      }
      if (startDate !== null) {
        where.push('u.used_date >= CAST(:startDate AS date)');
        params.startDate = startDate;
      }
      if (endDate !== null) {
        where.push('u.used_date <= CAST(:endDate AS date)');
        params.endDate = endDate;
      }
      const from = ' FROM leave_usage u WHERE ' + where.join(' AND ');
      const totalRows = await db.query('SELECT COUNT(*) AS total' + from, params);
      const items = await db.query(
        'SELECT u.leave_usage_id AS "leaveUsageId", u.used_date AS "usedDate", u.used_days AS "usedDays", ' +
          'u.attendance_request_id AS "attendanceRequestId"' +
          from +
          ' ORDER BY u.used_date DESC, u.leave_usage_id LIMIT CAST(:limit AS integer) OFFSET CAST(:offset AS integer)',
        { ...params, limit: size, offset: page * size },
      );
      return { items, page, size, total: Number(totalRows[0].total) };
    });
  }

  @Get('/leave-grant-rules')
  async listLeaveGrantRules(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const query = checks.queryOf(req.query) as Record<string, unknown>;
    const { page, size } = pageOf(query);
    return transaction(async (db) => {
      const totalRows = await db.query('SELECT COUNT(*) AS total FROM leave_grant_rule', {});
      const items = await db.query(
        'SELECT leave_grant_rule_id AS "leaveGrantRuleId", name AS "name", base_days AS "baseDays", ' +
          'additional_days AS "additionalDays", additional_condition AS "additionalCondition", use_status AS "useStatus" ' +
          'FROM leave_grant_rule ORDER BY leave_grant_rule_id LIMIT CAST(:limit AS integer) OFFSET CAST(:offset AS integer)',
        { limit: size, offset: page * size },
      );
      return { items, page, size, total: Number(totalRows[0].total) };
    });
  }

  @Patch('/leave-grant-rules/:leaveGrantRuleId')
  async updateLeaveGrantRule(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const data = checks.inputOf(req.body) as Record<string, unknown>;
    const idText = req.params['leaveGrantRuleId'];
    if (!/^\d+$/.test(idText)) {
      throw invalid('연차 생성 기준 ID 형식이 올바르지 않습니다.');
    }
    let name: string | null = null;
    if (!isBlank(data['name'])) {
      if (typeof data['name'] !== 'string' || data['name'].trim() === '' || data['name'].length > 100) {
        throw invalid('기준명은 100자 이하의 글자여야 합니다.');
      }
      name = data['name'];
    }
    const baseDays = optNonNegative(data['baseDays'], '기본일수');
    const additionalDays = optNonNegative(data['additionalDays'], '가산일수');
    let additionalCondition: string | null = null;
    if (!isBlank(data['additionalCondition'])) {
      if (typeof data['additionalCondition'] !== 'string' || data['additionalCondition'].length > 500) {
        throw invalid('가산 조건은 500자 이하의 글자여야 합니다.');
      }
      additionalCondition = data['additionalCondition'];
    }
    let useStatus: string | null = null;
    if (!isBlank(data['useStatus'])) {
      if (typeof data['useStatus'] !== 'string' || !USE_STATUSES.includes(data['useStatus'])) {
        throw invalid('사용 여부는 사용 또는 미사용이어야 합니다.');
      }
      useStatus = data['useStatus'];
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT leave_grant_rule_id FROM leave_grant_rule WHERE leave_grant_rule_id = CAST(:id AS bigint) FOR UPDATE',
        { id: idText },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'LEAVE_GRANT_RULE_NOT_FOUND', '연차 생성 기준을 찾을 수 없습니다.');
      }
      const rows = await db.query(
        'UPDATE leave_grant_rule SET ' +
          'name = COALESCE(CAST(:name AS varchar), name), ' +
          'base_days = COALESCE(CAST(:baseDays AS numeric), base_days), ' +
          'additional_days = COALESCE(CAST(:additionalDays AS numeric), additional_days), ' +
          'additional_condition = COALESCE(CAST(:additionalCondition AS varchar), additional_condition), ' +
          'use_status = COALESCE(CAST(:useStatus AS varchar), use_status), ' +
          'updated_at = now() ' +
          'WHERE leave_grant_rule_id = CAST(:id AS bigint) ' +
          'RETURNING leave_grant_rule_id AS "leaveGrantRuleId", use_status AS "useStatus"',
        { id: idText, name, baseDays, additionalDays, additionalCondition, useStatus },
      );
      return rows[0];
    });
  }
}

