import { useState } from 'react';
import {
  Band,
  Badge,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  ErrorText,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  Pager,
  Pairs,
  RefName,
  Select,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const TYPE_OPTIONS: [string, string][] = [
  ['연차', '연차'],
  ['반차', '반차'],
];
const USE_OPTIONS: [string, string][] = [
  ['사용', '사용'],
  ['미사용', '미사용'],
];

export default function FnSfr01808Page({ role, notify }: PageProps) {
  const [view, setView] = useState<'leave' | 'plan' | 'rule'>('leave');
  const isManager = role === '근태 담당자';

  return (
    <div className="doc">
      <h1>연차 설정 및 신청 관리</h1>
      <div>
        <button className={view === 'leave' ? '' : 'ghost'} onClick={() => setView('leave')}>잔여 연차</button>
        <button className={view === 'plan' ? '' : 'ghost'} onClick={() => setView('plan')}>월별 연차계획</button>
        {isManager && (
          <button className={view === 'rule' ? '' : 'ghost'} onClick={() => setView('rule')}>연차 발생 기준</button>
        )}
      </div>
      {view === 'leave' && <LeaveSection role={role} notify={notify} />}
      {view === 'plan' && <PlanSection role={role} />}
      {view === 'rule' && isManager && <RuleSection role={role} notify={notify} />}
    </div>
  );
}

function LeaveSection({ role, notify }: PageProps) {
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [baseYear, setBaseYear] = useState<number | string>('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [requesting, setRequesting] = useState(false);

  const list = useData<Page>(
    () => call<Page>('GET', '/annual-leaves', role, undefined, { ...applied, page }),
    [applied, page],
  );

  if (selected) {
    return <UsageDetail role={role} leave={selected} onBack={() => setSelected(null)} />;
  }

  return (
    <section className="box">
      <h2>잔여 연차와 집계현황</h2>
      <Filters
        onSearch={() => {
          setPage(0);
          setApplied({ employeeId, baseYear, departmentId });
        }}
        onReset={() => {
          setEmployeeId('');
          setBaseYear('');
          setDepartmentId('');
          setPage(0);
          setApplied({});
        }}
      >
        <Field label="임직원">
          <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
        </Field>
        <Field label="기준연도">
          <NumberInput value={baseYear} onChange={setBaseYear} />
        </Field>
        <Field label="부서 ID">
          <LookupSelect table="department" role={role} value={departmentId} onChange={setDepartmentId} />
        </Field>
      </Filters>
      <Band total={list.data?.total}>
        <button onClick={() => setRequesting(true)}>연차 신청</button>
      </Band>
      {list.error && <ErrorText text={list.error} />}
      <DataTable
        rows={list.data?.items ?? []}
        empty="조회된 연차가 없습니다. 조건을 바꿔 다시 조회해 주세요."
        onRowClick={(row) => setSelected(row)}
        columns={[
          { key: 'employeeId', label: '임직원', render: (r) => <RefName table="employee" role={role} value={r.employeeId} /> },
          { key: 'baseYear', label: '기준연도' },
          { key: 'grantedDays', label: '생성일수', render: (r) => <Num value={r.grantedDays} /> },
          { key: 'usedDays', label: '사용일수', render: (r) => <Num value={r.usedDays} /> },
          { key: 'remainingDays', label: '잔여일수', render: (r) => <Num value={r.remainingDays} /> },
        ]}
      />
      <Pager page={page} size={list.data?.size ?? 20} total={list.data?.total ?? 0} onPage={setPage} />
      {requesting && (
        <RequestDrawer
          role={role}
          notify={notify}
          onClose={() => setRequesting(false)}
          onDone={() => {
            setRequesting(false);
            list.reload();
          }}
        />
      )}
    </section>
  );
}

function UsageDetail({ role, leave, onBack }: { role: string; leave: Row; onBack: () => void }) {
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);

  const usages = useData<Page>(
    () => call<Page>('GET', '/leave-usages', role, undefined, { annualLeaveId: leave.annualLeaveId, ...applied, page }),
    [applied, page, leave.annualLeaveId],
  );

  return (
    <div>
      <button className="ghost" onClick={onBack}>목록으로 돌아가기</button>
      <section className="box">
        <h2>연차 요약</h2>
        <Pairs
          items={[
            ['임직원', <RefName table="employee" role={role} value={leave.employeeId} />],
            ['기준연도', String(leave.baseYear ?? '')],
            ['생성일수', <Num value={leave.grantedDays} />],
            ['사용일수', <Num value={leave.usedDays} />],
            ['잔여일수', <Num value={leave.remainingDays} />],
          ]}
        />
      </section>
      <section className="box">
        <h2>연차 사용내역</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setApplied({ startDate, endDate });
          }}
          onReset={() => {
            setStartDate('');
            setEndDate('');
            setPage(0);
            setApplied({});
          }}
        >
          <Field label="조회 시작일">
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="조회 종료일">
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
        </Filters>
        {usages.error && <ErrorText text={usages.error} />}
        <DataTable
          rows={usages.data?.items ?? []}
          empty="아직 사용한 연차가 없습니다."
          columns={[
            { key: 'usedDate', label: '사용일', render: (r) => <DateText value={r.usedDate} /> },
            { key: 'usedDays', label: '차감 일수', render: (r) => <Num value={r.usedDays} /> },
            { key: 'attendanceRequestId', label: '근태 ID' },
          ]}
        />
        <Pager page={page} size={usages.data?.size ?? 20} total={usages.data?.total ?? 0} onPage={setPage} />
      </section>
    </div>
  );
}

function RequestDrawer({
  role,
  notify,
  onClose,
  onDone,
}: PageProps & { onClose: () => void; onDone: () => void }) {
  const [attendanceType, setAttendanceType] = useState('연차');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [reason, setReason] = useState('');

  return (
    <Drawer title="연차 신청" onClose={onClose}>
      <Form
        submit="신청하고 결재 상신"
        note="신청하면 전자결재로 상신되며, 승인된 연차는 임의로 수정하거나 삭제할 수 없습니다."
        onSubmit={async () => {
          if (!startDate || !endDate) {
            throw new Error('시작일과 종료일을 입력해 주세요.');
          }
          await call('POST', '/attendance-requests', role, { attendanceType, startDate, endDate, reason });
          notify('연차를 신청했습니다.');
          onDone();
        }}
      >
        <Field label="근태 유형" required>
          <Select value={attendanceType} onChange={setAttendanceType} options={TYPE_OPTIONS} />
        </Field>
        <Field label="시작일" required>
          <DateInput value={startDate} onChange={setStartDate} />
        </Field>
        <Field label="종료일" required>
          <DateInput value={endDate} onChange={setEndDate} />
        </Field>
        <Field label="사유" wide>
          <TextInput value={reason} onChange={setReason} multiline />
        </Field>
      </Form>
    </Drawer>
  );
}

function PlanSection({ role }: { role: string }) {
  const [planMonth, setPlanMonth] = useState('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);

  const list = useData<Page>(
    () => call<Page>('GET', '/annual-leave-plans', role, undefined, { ...applied, page }),
    [applied, page],
  );

  return (
    <section className="box">
      <h2>월별 연차계획 현황</h2>
      <Filters
        onSearch={() => {
          setPage(0);
          setApplied({ planMonth, employeeId });
        }}
        onReset={() => {
          setPlanMonth('');
          setEmployeeId('');
          setPage(0);
          setApplied({});
        }}
      >
        <Field label="계획월" hint="YYYY-MM">
          <TextInput value={planMonth} onChange={setPlanMonth} />
        </Field>
        <Field label="임직원">
          <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
        </Field>
      </Filters>
      <Band total={list.data?.total} />
      {list.error && <ErrorText text={list.error} />}
      <DataTable
        rows={list.data?.items ?? []}
        empty="아직 등록한 연차계획이 없습니다."
        columns={[
          { key: 'employeeId', label: '임직원', render: (r) => <RefName table="employee" role={role} value={r.employeeId} /> },
          { key: 'planMonth', label: '계획월' },
          { key: 'planDates', label: '계획 일자', render: (r) => <DateText value={r.planDates} /> },
          { key: 'planDays', label: '계획 일수 합계', render: (r) => <Num value={r.planDays} /> },
          { key: 'approvalStatus', label: '승인 처리 상태', render: (r) => <Badge value={r.approvalStatus} /> },
        ]}
      />
      <Pager page={page} size={list.data?.size ?? 20} total={list.data?.total ?? 0} onPage={setPage} />
    </section>
  );
}

function RuleSection({ role, notify }: PageProps) {
  const [page, setPage] = useState(0);
  const [editing, setEditing] = useState<Row | null>(null);

  const list = useData<Page>(
    () => call<Page>('GET', '/leave-grant-rules', role, undefined, { page }),
    [page],
  );

  return (
    <section className="box">
      <h2>연차 발생 기준 설정</h2>
      <Band total={list.data?.total} />
      {list.error && <ErrorText text={list.error} />}
      <DataTable
        rows={list.data?.items ?? []}
        empty="아직 등록한 연차 발생 기준이 없습니다."
        onRowClick={(row) => setEditing(row)}
        columns={[
          { key: 'name', label: '기준명' },
          { key: 'baseDays', label: '기본일수', render: (r) => <Num value={r.baseDays} /> },
          { key: 'additionalDays', label: '가산일수', render: (r) => <Num value={r.additionalDays} /> },
          { key: 'additionalCondition', label: '가산 조건' },
          { key: 'useStatus', label: '사용 여부', render: (r) => <Badge value={r.useStatus} /> },
        ]}
      />
      <Pager page={page} size={list.data?.size ?? 20} total={list.data?.total ?? 0} onPage={setPage} />
      {editing && (
        <RuleDrawer
          role={role}
          notify={notify}
          rule={editing}
          onClose={() => setEditing(null)}
          onDone={() => {
            setEditing(null);
            list.reload();
          }}
        />
      )}
    </section>
  );
}

function RuleDrawer({
  role,
  notify,
  rule,
  onClose,
  onDone,
}: PageProps & { rule: Row; onClose: () => void; onDone: () => void }) {
  const [name, setName] = useState(String(rule.name ?? ''));
  const [baseDays, setBaseDays] = useState<number | string>((rule.baseDays as number | string) ?? '');
  const [additionalDays, setAdditionalDays] = useState<number | string>((rule.additionalDays as number | string) ?? '');
  const [additionalCondition, setAdditionalCondition] = useState(String(rule.additionalCondition ?? ''));
  const [useStatus, setUseStatus] = useState(String(rule.useStatus ?? '사용'));

  return (
    <Drawer title="연차 발생 기준 수정" onClose={onClose}>
      <Form
        submit="수정"
        note="수정한 기준은 이후 생성하는 연차부터 적용됩니다."
        onSubmit={async () => {
          if (!name.trim()) {
            throw new Error('기준명을 입력해 주세요.');
          }
          if (baseDays === '') {
            throw new Error('기본일수를 입력해 주세요.');
          }
          await call('PATCH', '/leave-grant-rules/' + String(rule.leaveGrantRuleId), role, {
            name,
            baseDays,
            additionalDays,
            additionalCondition,
            useStatus,
          });
          notify('연차 발생 기준을 수정했습니다.');
          onDone();
        }}
      >
        <Field label="기준명" required>
          <TextInput value={name} onChange={setName} />
        </Field>
        <Field label="기본일수" required>
          <NumberInput value={baseDays} onChange={setBaseDays} />
        </Field>
        <Field label="가산일수">
          <NumberInput value={additionalDays} onChange={setAdditionalDays} />
        </Field>
        <Field label="가산 조건" wide>
          <TextInput value={additionalCondition} onChange={setAdditionalCondition} multiline />
        </Field>
        <Field label="사용 여부" required>
          <Select value={useStatus} onChange={setUseStatus} options={USE_OPTIONS} />
        </Field>
      </Form>
    </Drawer>
  );
}
